'use strict';

function toggleExclusiveSection(state, name) {
  if (!state || typeof state !== 'object' || Array.isArray(state) ||
      Object.getPrototypeOf(state) !== Object.prototype ||
      Object.values(state).some((value) => typeof value !== 'boolean')) {
    throw new TypeError('state must be a plain boolean map');
  }
  if (typeof name !== 'string') {
    throw new TypeError('name must be a string');
  }
  if (!Object.prototype.hasOwnProperty.call(state, name)) {
    throw new RangeError('unknown section');
  }

  const result = { ...state };
  result[name] = !result[name];
  return result;
}

module.exports = toggleExclusiveSection;

