'use strict';

const assert = require('node:assert');
const toggleExclusiveSection = require('./solution');

assert.strictEqual(typeof toggleExclusiveSection, 'function');

const closed = Object.freeze({ overview: false, details: false, history: true });
const opened = toggleExclusiveSection(closed, 'details');
assert.deepStrictEqual(opened, { overview: false, details: true, history: false });
assert.deepStrictEqual(Object.keys(opened), ['overview', 'details', 'history']);
assert.notStrictEqual(opened, closed);
assert.deepStrictEqual(closed, { overview: false, details: false, history: true });

const active = Object.freeze({ first: false, second: true, third: false });
const allClosed = toggleExclusiveSection(active, 'second');
assert.deepStrictEqual(allClosed, { first: false, second: false, third: false });
assert.deepStrictEqual(Object.keys(allClosed), ['first', 'second', 'third']);

const singleton = { only: false };
assert.deepStrictEqual(toggleExclusiveSection(singleton, 'only'), { only: true });

for (const state of [null, [], 'state', new Date(), { a: false, b: 1 }]) {
  assert.throws(() => toggleExclusiveSection(state, 'a'), TypeError);
}
for (const name of [null, 1, {}]) {
  assert.throws(() => toggleExclusiveSection({ a: false }, name), TypeError);
}
assert.throws(() => toggleExclusiveSection({}, 'anything'), RangeError);
assert.throws(() => toggleExclusiveSection({ a: false }, 'missing'), RangeError);

